<script setup lang="ts">
import Icon from './Icon.vue';
import{ref,onUnmounted,onMounted}from'vue';import{t,bytes,duration,errorText}from'./i18n';import{api}from'./api';import{putTask,getTask,changeTask,release,renew}from'../../../packages/storage';import type{Task,Settings}from'../../../packages/contracts';
import{installAnnotations,removeAnnotations}from'./annotations';
const props=defineProps<{captureToken?:string;sourceTabId?:number}>();
const actualResolution=ref('');let audioOutput:AudioContext|undefined;
const emit=defineEmits<{ready:[id:string];changed:[]}>();
const recording=ref(false),starting=ref(false),elapsed=ref(0),written=ref(0),error=ref(''),hasAudio=ref(true);const owner=crypto.randomUUID();let recorder:MediaRecorder|undefined,stream:MediaStream|undefined,writer:Worker|undefined,timer:ReturnType<typeof setInterval>|undefined,taskId='';let requestId=0,queue=Promise.resolve(),queuedBytes=0,closed=false,writerFailed=false;
const requests=new Map<number,{resolve:(n:number)=>void;reject:(e:Error)=>void}>();
function send(type:string,buffer?:ArrayBuffer){return new Promise<number>((resolve,reject)=>{if(!writer||writerFailed){reject(new Error('interrupted'));return;}const id=++requestId;requests.set(id,{resolve,reject});writer!.postMessage({id,type,taskId,buffer},buffer?[buffer]:[]);});}
function stop(){if(recorder&&recorder.state!=='inactive')recorder.stop();}
async function start(streamId?:string){
 error.value='';starting.value=true;
 // Invoke the chooser directly in this click's activation, before storage awaits.
 const capture=streamId?navigator.mediaDevices.getUserMedia({audio:{mandatory:{chromeMediaSource:'tab',chromeMediaSourceId:streamId}} as MediaTrackConstraints,video:{mandatory:{chromeMediaSource:'tab',chromeMediaSourceId:streamId,maxWidth:3840,maxHeight:2160,maxFrameRate:30}} as MediaTrackConstraints}):navigator.mediaDevices.getDisplayMedia({video:{displaySurface:'browser',width:{ideal:3840},height:{ideal:2160},frameRate:30},audio:true});
 try{
  stream=await capture;await navigator.locks.request('alcydeo:recording',{ifAvailable:true},async lock=>{
   if(!lock)throw new Error('busy');
   const video=stream!.getVideoTracks()[0];if(!video)throw new Error('unsupported');const capturePrefs=(await api('snapshot')).settings as Settings,quality=capturePrefs.captureQuality??'high',target=quality==='standard'?{width:1280,height:720}:quality==='high'?{width:1920,height:1080}:{width:3840,height:2160};const native=video.getSettings(),scale=Math.min(1,target.width/(native.width||target.width),target.height/(native.height||target.height));await video.applyConstraints({width:{ideal:Math.round((native.width||target.width)*scale),max:target.width},height:{ideal:Math.round((native.height||target.height)*scale),max:target.height},frameRate:{ideal:30,max:30}});const measured=video.getSettings();actualResolution.value=`${measured.width??0} × ${measured.height??0}`;const videoBitrate=Math.max(8000000,Math.min(32000000,(measured.width??1920)*(measured.height??1080)*30*.16));
   const mime=MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus')?'video/webm;codecs=vp9,opus':'video/webm;codecs=vp8,opus';if(!MediaRecorder.isTypeSupported(mime))throw new Error('codec');hasAudio.value=!!stream!.getAudioTracks().length;
   const prefs=(await api('snapshot')).settings as Settings;taskId=crypto.randomUUID();const now=Date.now();const source=props.sourceTabId!==undefined?await chrome.tabs.get(props.sourceTabId).catch(()=>undefined):undefined;if(stream!.getAudioTracks().length&&streamId){audioOutput=new AudioContext();audioOutput.createMediaStreamSource(stream!).connect(audioOutput.destination);void audioOutput.resume();}
   const task:Task={id:taskId,title:source?.title??`Alcydeo ${new Date(now).toISOString().replace('T',' ').slice(0,19)}`,media:{id:taskId,tabId:props.sourceTabId??-1,pageUrl:source?.url??'',url:'',kind:'direct',title:t('recording'),contentType:'video/webm',variants:[]},variant:{id:'recording',url:'',label:`${measured.height??1080}p`,contentType:'video/webm'},state:'recording',createdAt:now,updatedAt:now,bytes:0,progress:0,checkpoints:{},recording:{file:'recording.webm',startedAt:now,active:true,sessionKey:props.captureToken},destination:{folder:prefs.folder,saveAs:prefs.saveAs},owner,leaseUntil:now+30000};await putTask(task);
   writerFailed=false;writer=new Worker(new URL('./recording.worker.ts',import.meta.url),{type:'module'});writer.onmessage=event=>{const pending=requests.get(event.data.id);if(!pending)return;requests.delete(event.data.id);if(event.data.error)pending.reject(new Error(event.data.error));else pending.resolve(event.data.bytes);};writer.onerror=()=>{writerFailed=true;for(const pending of requests.values())pending.reject(new Error('interrupted'));requests.clear();stop();};await send('open');
   recorder=new MediaRecorder(stream!,{mimeType:mime,videoBitsPerSecond:videoBitrate,audioBitsPerSecond:192000});queue=Promise.resolve();queuedBytes=0;written.value=0;elapsed.value=0;closed=false;
   recorder.ondataavailable=event=>{
    if(!event.data.size)return;
    // A blocked disk or suspended renderer must not accumulate a whole stream in RAM.
    if(queuedBytes+event.data.size>16*1024*1024){error.value='recordingSlow';stop();return;}
    queuedBytes+=event.data.size;queue=queue.then(async()=>{const buffer=await event.data.arrayBuffer();const size=await send('write',buffer);queuedBytes-=event.data.size;written.value=size;await changeTask(taskId,t=>{t.bytes=size;t.recording!.duration=elapsed.value;});}).catch(e=>{error.value=e.message;stop();});
   };
   const ended=new Promise<void>(resolve=>{recorder!.onstop=()=>resolve();});recorder.onerror=()=>{error.value='interrupted';stop();};video.onended=stop;
   let polling=false;timer=setInterval(()=>{elapsed.value=(Date.now()-now)/1000;if(polling)return;polling=true;void getTask(taskId).then(async current=>{if(!current||current.state!=='recording'||!current.recording?.active)stop();else await renew(taskId,owner);}).catch(()=>{error.value='interrupted';stop();}).finally(()=>{polling=false;});},1000);
   recorder.start(1000);recording.value=true;starting.value=false;emit('changed');await ended;recording.value=false;clearInterval(timer);stream?.getTracks().forEach(t=>t.stop());await queue;await send('close');closed=true;
   const current=await getTask(taskId);if(current?.state==='cancelled')return;
   const file=await(await(await navigator.storage.getDirectory()).getDirectoryHandle(taskId)).getFileHandle('recording.webm').then(h=>h.getFile());const{validate}=await import('../../../packages/media-core/engine');const validation=await validate(file);
   await changeTask(taskId,t=>{t.recording!.active=false;t.state='validating';t.validation=validation;t.output='recording.webm';t.bytes=file.size;t.progress=1;t.error=error.value||undefined;if(error.value)t.notices=['recordingIncomplete'];});await release(taskId,owner);emit('ready',taskId);
  });
 }catch(e){const name=(e as {name?:string})?.name;error.value=name==='NotAllowedError'?'recordingDenied':['NotReadableError','NotFoundError','OverconstrainedError','NotSupportedError'].includes(name??'')?'recordingUnavailable':e instanceof Error?e.message:'unsupported';if(props.captureToken)void chrome.tabs.getCurrent().then(tab=>tab?.id!==undefined?chrome.tabs.update(tab.id,{active:true}):undefined);if(taskId)await changeTask(taskId,t=>{if(t.state==='recording'){t.state='paused';t.recording!.active=false;t.error='recordingInterrupted';}}).catch(()=>{});}
 finally{await audioOutput?.close().catch(()=>{});audioOutput=undefined;if(props.sourceTabId!==undefined&&props.captureToken)await chrome.scripting.executeScript({target:{tabId:props.sourceTabId},func:removeAnnotations,args:[props.captureToken]}).catch(()=>{});clearInterval(timer);stream?.getTracks().forEach(t=>t.stop());if(writer&&!closed)await send('close').catch(()=>{});writer?.terminate();writer=undefined;if(taskId)await release(taskId,owner).catch(()=>{});recording.value=false;starting.value=false;emit('changed');}
}
async function annotate(){if(props.sourceTabId===undefined)return;await chrome.scripting.executeScript({target:{tabId:props.sourceTabId},func:installAnnotations,args:[props.captureToken??taskId,{draw:t('annotations'),undo:t('undoAnnotations'),clear:t('clearAnnotations'),close:t('close')}]});await chrome.tabs.update(props.sourceTabId,{active:true});}
let consuming=false;async function consume(){if(!props.captureToken||consuming||recording.value)return;const key=`capture:${props.captureToken}`,data=(await chrome.storage.session.get(key))[key] as {streamId:string;consumerTabId:number;sourceTabId:number;createdAt:number}|undefined;if(!data)return;const current=await chrome.tabs.getCurrent();if(data.consumerTabId!==current?.id||data.sourceTabId!==props.sourceTabId||Date.now()-data.createdAt>15000)return;consuming=true;await chrome.storage.session.remove(key);await start(data.streamId);}
const captureChanged=(changes:Record<string,chrome.storage.StorageChange>,area:string)=>{if(area==='session'&&props.captureToken&&changes[`capture:${props.captureToken}`]?.newValue)void consume();};onMounted(()=>{chrome.storage.onChanged.addListener(captureChanged);void consume();});

async function nativeCapture(){if(starting.value||recording.value)return;try{error.value='';starting.value=true;if(!await chrome.permissions.contains({permissions:['tabCapture']}))throw new Error('recordingDenied');const tab=await chrome.tabs.getCurrent();if(tab?.id===undefined||props.sourceTabId===undefined)throw new Error('recordingUnavailable');const id=await chrome.tabCapture.getMediaStreamId({targetTabId:props.sourceTabId,consumerTabId:tab.id});await start(id);}catch(e){error.value=(e as Error).message==='recordingDenied'?'recordingDenied':'recordingUnavailable';starting.value=false;const tab=await chrome.tabs.getCurrent();if(tab?.id!==undefined)await chrome.tabs.update(tab.id,{active:true});}}
const startMessage=(message:any,sender:chrome.runtime.MessageSender,reply:(value:unknown)=>void)=>{if(message?.type!=='alcydeo.quickCapture'||!props.captureToken||message.token!==props.captureToken||sender.id!==chrome.runtime.id||!sender.url?.startsWith(chrome.runtime.getURL('/popup.html')))return false;if(!consuming&&!recording.value){consuming=true;void nativeCapture();}reply({started:true});return false;};
chrome.runtime.onMessage.addListener(startMessage);
onUnmounted(()=>{chrome.runtime.onMessage.removeListener(startMessage);chrome.storage.onChanged.removeListener(captureChanged);stop();stream?.getTracks().forEach(t=>t.stop());clearInterval(timer);});
</script>
<template><section class="settings-card recording-panel"><h2 class="panel-title"><Icon name="record" />{{ t('captureMode') }}</h2><p>{{ t('recordHint') }}</p><div v-if="error" class="alert" role="alert">{{ errorText(error) }}</div><p v-if="recording" role="status"><strong class="recording-live">● {{ t('recording') }}</strong> · {{ duration(elapsed) }} · {{ bytes(written) }}</p><p v-if="recording"><bdi>{{ actualResolution }}</bdi> · {{ t('captureHighBitrate') }}</p><button v-if="recording && sourceTabId !== undefined" class="secondary annotation-button" @click="annotate">✎ {{ t('annotations') }}</button><p v-if="recording && !hasAudio" class="task-notice">{{ t('recordNoAudio') }}</p><button v-if="!recording" class="primary" :disabled="starting" @click="captureToken ? nativeCapture() : start()"><Icon name="record" />{{ t('startRecording') }}</button><button v-else class="primary" @click="stop"><Icon name="stop" />{{ t('stopRecording') }}</button></section></template>
